import sys; sys.path.insert(0, "src")
import pandas as pd, numpy as np
from fleetrisk import config, pipeline, io_layer, observation

REF = pd.read_csv("reference/scores_reference.csv")
def cmp(scores):
    m = REF[["flight_id","risk_score"]].merge(scores[["flight_id","risk_score"]], on="flight_id")
    d = (m.risk_score_x-m.risk_score_y).abs()
    same = int((d<=1e-6).sum())
    return f"rows {len(m)} agree {same} ({same/len(m):.4f}) maxdiff {d.max():.6f} mean {m.risk_score_y.mean():.6f} watch {scores.watch.mean():.6f}"

CFG = config.load("configs/reference.yaml")
FL = io_layer.read_flights(CFG)
GR = io_layer.read_groundings(CFG)
EXPORT_END = FL["departed_at"].max()
FIT_END = pd.Timestamp("2024-02-15")+pd.Timedelta(days=1)-pd.Timedelta(seconds=1)

ev = pd.concat([
    FL[["flight_id","tail_number","departed_at"]].assign(kind="f", t=FL["departed_at"]),
    GR[["tail_number"]].assign(kind="g", t=GR["occurred_at"]),
]).sort_values(["tail_number","t"], kind="stable").reset_index(drop=True)
ev["next_kind"] = ev.groupby("tail_number").kind.shift(-1)
ev["next_t"] = ev.groupby("tail_number").t.shift(-1)
EVT = ev[ev.kind=="f"].set_index("flight_id")[["next_kind","next_t"]]
FL_J = FL.set_index("flight_id").join(EVT)

def att(mode):
    def f(flights, groundings, w):
        out = flights.copy()
        j = FL_J.loc[out.flight_id]
        d = out.departed_at.to_numpy()
        nk = j.next_kind.to_numpy(); nt = j.next_t.to_numpy()
        dl = d + np.timedelta64(w,"D")
        if mode=="any_in":
            m = flights.merge(groundings[["tail_number","occurred_at"]], on="tail_number", how="left")
            hit = (m.occurred_at>m.departed_at)&(m.occurred_at<=m.departed_at+pd.Timedelta(days=w))
            lab = hit.groupby(m.flight_id).any().reindex(out.flight_id).fillna(False).to_numpy()
        elif mode=="next_in":
            lab = (nk=="g") & (nt <= dl)
        elif mode=="next_any":
            lab = nk=="g"
        out["label"] = lab.astype(int)
        return out
    return f

def obs(mode):
    def f(df, spec, ee, w):
        j = FL_J.loc[df.flight_id]
        nt = j.next_t.to_numpy()
        dl = df.departed_at.to_numpy() + np.timedelta64(w,"D")
        if mode=="export": return pd.Series(dl <= np.datetime64(ee), index=df.index)
        if mode=="fit_end": return pd.Series(dl <= np.datetime64(FIT_END), index=df.index)
        if mode=="next_or_export":
            known = (nt == nt)  # not NaT
            return pd.Series(known | (dl <= np.datetime64(ee)), index=df.index)
        if mode=="none": return pd.Series(True, index=df.index)
    return f

for lm in ["next_in","next_any","any_in"]:
    for om in ["none","export","fit_end","next_or_export"]:
        observation.attach_label = att(lm)
        observation.observed = obs(om)
        try:
            scores,_,_ = pipeline.run(CFG)
        except Exception as e:
            print(lm, om, "ERR", repr(e)[:80]); continue
        print(lm, om, "->", cmp(scores))
EOF
