import pandas as pd, numpy as np
from fleetrisk import config, pipeline, io_layer, observation

REF = pd.read_csv("reference/scores_reference.csv")
REF_MEAN = REF.risk_score.mean(); REF_WATCH = REF.watch.mean()

CFG = config.load("configs/reference.yaml")

def report(scores, tag):
    m = REF[["flight_id","risk_score"]].merge(scores[["flight_id","risk_score"]], on="flight_id")
    d = (m.risk_score_x-m.risk_score_y).abs()
    agree = int((d<=1e-6).sum())
    print("%-28s agree %6d/%d (%.4f) maxdiff %.4f | mean %.6f (ref %.6f) watch %.6f (ref %.6f)"
          % (tag, agree, len(m), agree/len(m), d.max(),
             m.risk_score_y.mean(), REF_MEAN, scores.watch.mean(), REF_WATCH), flush=True)

variants = {}
for lo_inc in (False, True):
    for hi_inc in (False, True):
        for win_end in ("fit", "export"):
            name = ("[%s," if lo_inc else "(%s,") % "d" + ("%s]" if hi_inc else "%s)") % "d+3"
            name += "/" + win_end

            def mk_att(lo_inc=lo_inc, hi_inc=hi_inc):
                def att(flights, groundings, w):
                    out = flights.copy()
                    m = flights.merge(groundings[["tail_number","occurred_at"]], on="tail_number", how="left")
                    hi = m.departed_at + pd.Timedelta(days=w)
                    a = (m.occurred_at >= m.departed_at) if lo_inc else (m.occurred_at > m.departed_at)
                    b = (m.occurred_at <= hi) if hi_inc else (m.occurred_at < hi)
                    out["label"] = m.flight_id.map((a&b).groupby(m.flight_id).any()).fillna(False).astype(int)
                    return out
                return att
            def mk_obs(win_end=win_end):
                def obsf(df, spec, ee, w):
                    if win_end=="fit":
                        end = pd.Timestamp(spec["to"])+pd.Timedelta(days=1)-pd.Timedelta(seconds=1)
                    else:
                        end = pd.Timestamp(ee)
                    return pd.Series(df.departed_at+pd.Timedelta(days=w)<=end, index=df.index)
                return obsf
            variants[name] = (mk_att(), mk_obs())

for name, (att, obsf) in variants.items():
    observation.attach_label = att
    observation.observed = obsf
    try:
        scores,_,_ = pipeline.run(CFG)
    except Exception as e:
        print(name, "ERR", repr(e)[:80]); continue
    report(scores, name)
"}

